var n=`0693-palm-butter-stew`;var i=`world-0693`;var a=`LR`;var s=`western-africa`;var r=4;var o=81;var l={en:`Palm Butter Stew`,ua:`Рагу з пальмової олії`};var g={en:`Palm Butter Stew is a Liberia classic prepared with goat meat, yellow onion, palm nut concentrate, fish (unspecified). A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Рагу з пальмової олії, страва кухні країни Ліберія зі складниками: козлятина, жовта цибуля, концентрат пальмових плодів, риба (невизначений вид). Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`goat-meat`,550,`g`],[`red-palm-oil`,40,`ml`],[`yellow-onion`,170,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`palm-nut-concentrate`,260,`g`],[`water`,850,`ml`],[`fish-unspecified`,330,`g`],[`tomato`,250,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`spinach`,180,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]}];var u={slug:n,id:i,country:`LR`,region:s,servings:4,minutes:81,title:l,text:g,steps:m};export{a as country,u as default,i as id,o as minutes,s as region,r as servings,n as slug,m as steps,g as text,l as title};